ST.xhtml:p:
RTrigger3(CLK := g_bFrontSupportPendingControlM);
IF RTrigger3.Q THEN
  g_bFrontSupportPendingControlM := FALSE;
  g_bFrontSupportPendingFlag := FALSE;
  nPreFollowStep := nFollowStep;
  IF NOT bDynamicFollowUp THEN
    M.ENABLE[319] := 0;
  ELSE
    IF M.PARAMETER_P[319] = 0.0 THEN
		  IF ABS(M.PARAMETER_Q[319]) >= 180.0 THEN
				IF g_nFrontSusutainCount >= 1 AND  g_bFrontAxis1VelAddEnable THEN
				  g_bFrontSupportPendingFlag := TRUE;
				  g_bSustain4AbsPosition := g_fSustain4ToChuckDist - SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0);
				  g_bSustain4Abs := TRUE;
				END_IF;

				IF g_nFrontSusutainCount >= 2 AND  g_bFrontAxis2VelAddEnable THEN
				  g_bFrontSupportPendingFlag := TRUE;
				  g_bSustain5AbsPosition := g_fSustain5ToChuckDist - SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0);
				  g_bSustain5Abs := TRUE;
				END_IF;
				IF g_nFrontSusutainCount >= 3 AND  g_bFrontAxis3VelAddEnable THEN
				  g_bFrontSupportPendingFlag := TRUE;
				  g_bSustain6AbsPosition := g_fSustain6ToChuckDist - SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0);
				  g_bSustain6Abs := TRUE;
				END_IF;
                IF g_nFrontSusutainCount >= 4 AND  g_bFrontAxis4VelAddEnable THEN
				  g_bFrontSupportPendingFlag := TRUE;
				  g_fARAbsPosition2 := g_fSustain6ToChuckDist - SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0);
				  g_bAntiRejection2AbsExecute := TRUE;
				END_IF;

		  END_IF;
       M.ENABLE[319] := 0;
	  ELSE
      IF g_nFrontSusutainCount >= 1 AND g_bFrontAxis1VelAddEnable AND g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS1Dis THEN
        g_bSustain4AbsPosition := g_fSustain4ToChuckDist - g_fSustainTargetPos;
        g_bSustain4Abs := TRUE;
      END_IF;
      IF g_nFrontSusutainCount >= 2 AND g_bFrontAxis2VelAddEnable AND g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS2Dis THEN
        g_bSustain5AbsPosition := g_fSustain5ToChuckDist - g_fSustainTargetPos;
        g_bSustain5Abs := TRUE;
      END_IF;
      IF g_nFrontSusutainCount >= 3 AND g_bFrontAxis3VelAddEnable AND g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS3Dis THEN
        g_bSustain6AbsPosition := g_fSustain6ToChuckDist - g_fSustainTargetPos;
        g_bSustain6Abs := TRUE;
      END_IF;
      IF g_nFrontSusutainCount >= 4 AND g_bFrontAxis4VelAddEnable AND g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowZ4Dis THEN
        g_fARAbsPosition2 := g_dFrontSustainAxis7ChuckDist - g_fSustainTargetPos;
        g_bAntiRejection2AbsExecute := TRUE;
      END_IF;
      M.ENABLE[319] := 0;
    END_IF; 
  END_IF; 
END_IF;





RTrigger1(CLK := g_bFrontSustainFollowExecuteM);
RTrigger2(CLK := g_biFrontSustainFollowClose);

IF RTrigger1.Q THEN
  (*托料轴*)
  IF g_bFrontSustainEnable THEN
    IF LREAL_TO_INT(g_nFrontSustainSignalM) = 0 THEN
      (*关闭浮动*)
      nFollowStep := 100;
      bDynamicFollowS1Up := FALSE;
      bDynamicFollowS2Up := FALSE;
      bDynamicFollowS3Up := FALSE;
      bDynamicFollowS4Up := FALSE;
      g_bFrontAxis1VelAddEnable := FALSE;
      g_bFrontAxis2VelAddEnable := FALSE;
      g_bFrontAxis3VelAddEnable := FALSE;
      g_bFrontAxis4VelAddEnable := FALSE;
    ELSIF LREAL_TO_INT(g_nFrontSustainSignalM) = 1 THEN
      (*浮动*)
      nFollowStep := 10;
      (*不开启托料轴自动浮动依旧升起托料轴
      ELSE
        nFollowStep := 420;
      *)
      g_boFrontSustainFollowDone := FALSE;
      g_bSustain4AbsDone := FALSE;
      g_bSustain5AbsDone := FALSE;
      g_bSustain6AbsDone := FALSE;
      g_bAntiRejection2AbsDone := FALSE;
    ELSE(*处理回中或其他，只浮动*)
      nFollowStep := 600;
    END_IF;
  (*托料气缸*)
  ELSIF g_bBlankCylinderEnable THEN
    IF LREAL_TO_INT(g_nFrontSustainSignalM) = 0 THEN
      nFollowStep := 140;
      IF g_nBlankClylinderCount = 0 THEN
        g_boFrontSustainFollowDone := TRUE;
        M.ENABLE[222] := 0;
        g_bExecuteFinishedM222 := FALSE;
        nFollowStep := 0;
      END_IF;

    ELSIF LREAL_TO_INT(g_nFrontSustainSignalM) = 1 THEN
      (*托料气缸上升*)
      IF bDynamicFollowUp THEN
        nFollowStep := 400;
      ELSE
        nFollowStep := 160;
      END_IF;
      g_boFrontSustainFollowDone := FALSE;
    ELSE(*此处进，说明是回中或其他，直接跳过*)
      g_boFrontSustainFollowDone := TRUE; 
      M.ENABLE[222] := 0;
      g_bExecuteFinishedM222 := FALSE;
    END_IF;
  ELSE
    g_boFrontSustainFollowDone := TRUE; 
    M.ENABLE[222] := 0;
    g_bExecuteFinishedM222 := FALSE;
  END_IF;
  g_dDynamicCoordTemp := g_diYMachineCoordinate;
  g_bFrontSustainFollowExecuteM := FALSE;
END_IF;

CASE nFollowStep OF
  0:
    nFollowStep := 0;
  10:
  IF g_nFrontSusutainCount >= 1 AND NOT g_bFrontSustainAxis1CloseVelAdd THEN
    g_bSustain4Abs := TRUE;
    g_bSustain4AbsPosition := g_dFrontSustainAxis4DownPos;
    g_bSustain4AbsDone := FALSE;
  END_IF;
  IF g_nFrontSusutainCount >= 2 AND NOT g_bFrontSustainAxis2CloseVelAdd  THEN
     g_bSustain5Abs := TRUE;
    g_bSustain5AbsPosition := g_dFrontSustainAxis5DownPos;
    g_bSustain5AbsDone := FALSE;
  END_IF;

  IF g_nFrontSusutainCount >= 3 AND NOT g_bFrontSustainAxis3CloseVelAdd THEN
     g_bSustain6Abs := TRUE;
    g_bSustain6AbsPosition := g_dFrontSustainAxis6DownPos;
    g_bSustain6AbsDone := FALSE;
  END_IF;
  IF g_nFrontSusutainCount >= 4 AND NOT g_bFrontSustainAxis4CloseVelAdd THEN
     g_bAntiRejection2AbsExecute := TRUE;
    g_fARAbsPosition2 := g_dFrontSustainAxis7DownPos;
    g_bAntiRejection2AbsDone := FALSE;
  END_IF;

  nFollowStep := 11;
  IF g_nFrontSusutainCount = 0 THEN
    nFollowStep := 0;
    M.ENABLE[222] := 0;
    g_bExecuteFinishedM222 := FALSE;
    g_boFrontSustainFollowDone := TRUE;
  END_IF;
  11:
  bCheckFlag4 := TRUE;
   IF (NOT g_bSustain4AbsDone) AND g_nFrontSusutainCount >= 1 AND NOT g_bFrontSustainAxis1CloseVelAdd THEN

      bCheckFlag4 := FALSE; 
    END_IF;
    IF (NOT g_bSustain5AbsDone) AND g_nFrontSusutainCount >= 2 AND NOT g_bFrontSustainAxis2CloseVelAdd THEN
      bCheckFlag4 := FALSE;
    END_IF;
    IF (NOT g_bSustain6AbsDone) AND g_nFrontSusutainCount >= 3 AND NOT g_bFrontSustainAxis3CloseVelAdd  THEN

      bCheckFlag4 := FALSE;
    END_IF;
    IF (NOT g_bAntiRejection2AbsDone) AND g_nFrontSusutainCount >= 4 AND NOT g_bFrontSustainAxis4CloseVelAdd  THEN

      bCheckFlag4 := FALSE;
    END_IF;

  IF bCheckFlag4 THEN
    nFollowStep := 15;
    g_bSustain4AbsDone := FALSE;
    g_bSustain5AbsDone := FALSE;
    g_bSustain6AbsDone := FALSE;
    g_bAntiRejection2AbsDone := FALSE;
  END_IF;

  15:(*判断是否要浮动*)
    fActPos := g_fSustainTargetPos;
    IF g_nFrontSusutainCount >= 1 AND g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS1Dis AND (NOT g_bSustain4InFollow)  AND NOT bDynamicFollowS1Up AND NOT g_bFrontSustainAxis1CloseVelAdd THEN
      g_bSustain4AbsPosition := g_fSustain4ToChuckDist - fActPos;
      g_bSustain4Abs := TRUE;
      bDynamicFollowS1Up := TRUE;
      g_bFrontAxis1VelAddEnable := TRUE;
    END_IF;
    IF g_nFrontSusutainCount >= 2 AND g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS2Dis AND (NOT g_bSustain5InFollow) AND NOT bDynamicFollowS2Up AND NOT g_bFrontSustainAxis2CloseVelAdd THEN
        g_bSustain5AbsPosition := g_fSustain5ToChuckDist - fActPos;
        g_bSustain5Abs := TRUE;
        bDynamicFollowS2Up := TRUE;
        g_bFrontAxis2VelAddEnable := TRUE;
    END_IF;
    IF g_nFrontSusutainCount >= 3 AND g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS3Dis AND (NOT g_bSustain6InFollow) AND NOT bDynamicFollowS3Up AND NOT g_bFrontSustainAxis3CloseVelAdd THEN
      g_bSustain6AbsPosition := g_fSustain6ToChuckDist - fActPos;
      g_bSustain6Abs := TRUE;
      bDynamicFollowS3Up := TRUE;
      g_bFrontAxis3VelAddEnable := TRUE;
    END_IF;
    IF g_nFrontSusutainCount >= 4 AND g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowZ4Dis AND NOT bDynamicFollowS4Up AND NOT g_bFrontSustainAxis4CloseVelAdd THEN
      g_fARAbsPosition2 := g_dFrontSustainAxis7ChuckDist - fActPos;
      g_bAntiRejection2AbsExecute := TRUE;
      bDynamicFollowS4Up := TRUE;
      g_bFrontAxis4VelAddEnable := TRUE;
    END_IF;
    M.ENABLE[222] := 0;
    g_bExecuteFinishedM222 := FALSE;
    g_boFrontSustainFollowDone := TRUE;
    IF g_bPlcPauseBuffer THEN
       nFollowStep := 16;
    END_IF;
  16:
	IF g_bPlcStartBuffer THEN
       nFollowStep := 15;
       bDynamicFollowS1Up := FALSE;
       bDynamicFollowS2Up := FALSE;
       bDynamicFollowS3Up := FALSE;
       bDynamicFollowS4Up := FALSE;
    END_IF;
  100:
     IF g_nFrontSusutainCount >= 1 THEN
      g_bSustain4Follow := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 2 THEN
      g_bSustain5Follow := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 3 THEN
      g_bSustain6Follow := FALSE;
    END_IF;
    nFollowStep := 105;
  105:
    IF g_nFrontSusutainCount >= 1 THEN
      g_bSustain4InFollow := FALSE;
      g_Sustain4Stop.EXECUTE := TRUE;
    END_IF;
    IF g_nFrontSusutainCount >= 2 THEN
      g_bSustain5InFollow := FALSE;
      g_Sustain5Stop.EXECUTE := TRUE;
    END_IF;
    IF g_nFrontSusutainCount >= 3 THEN
       g_bSustain6InFollow := FALSE;
      g_Sustain6Stop.EXECUTE := TRUE;
    END_IF;
    IF g_nFrontSusutainCount >= 4 THEN
      g_AntiRejection2Stop.EXECUTE := TRUE;
    END_IF;
	bCheckFlag := TRUE;
    IF g_nFrontSusutainCount >= 1 AND NOT g_Sustain4Stop.DONE THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 2 AND NOT g_Sustain5Stop.DONE THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 3 AND NOT g_Sustain6Stop.DONE THEN
       bCheckFlag := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 4 AND NOT g_AntiRejection2Stop.DONE THEN
       bCheckFlag := FALSE;
    END_IF;
	IF bCheckFlag THEN
      nFollowStep := 110;
      g_Sustain6Stop.EXECUTE := FALSE;
      g_Sustain5Stop.EXECUTE := FALSE;
      g_Sustain4Stop.EXECUTE := FALSE;
      g_AntiRejection2Stop.EXECUTE := FALSE;
    END_IF;
  110:
    g_boFrontSustainFollowDone := TRUE;
    g_boFrontSustainUpDownDone := FALSE;
    g_bFrontSustainUpDownDone := FALSE;
    nFollowStep := 120;
  120:
    IF g_nFrontSusutainCount >= 1 THEN
      g_bSustain4Abs := TRUE;
      IF Axis_Sustain4.NCTOPLC.SETPOS <= 0.0 THEN
        g_bSustain4AbsPosition := Axis_Sustain4.NCTOPLC.SETPOS;
      ELSE
        g_bSustain4AbsPosition := g_dFrontSustainAxis4DownPos;
      END_IF;
    END_IF;
    IF g_nFrontSusutainCount >= 2 THEN
      g_bSustain5Abs := TRUE;
      IF Axis_Sustain5.NCTOPLC.SETPOS <= 0.0 THEN
        g_bSustain5AbsPosition := Axis_Sustain5.NCTOPLC.SETPOS;
      ELSE
        g_bSustain5AbsPosition := g_dFrontSustainAxis5DownPos;
      END_IF;
    END_IF;
    IF g_nFrontSusutainCount >= 3 THEN
      g_bSustain6Abs := TRUE;
      IF Axis_Sustain6.NCTOPLC.SETPOS <= 0.0 THEN
        g_bSustain6AbsPosition := Axis_Sustain6.NCTOPLC.SETPOS;
      ELSE
        g_bSustain6AbsPosition := g_dFrontSustainAxis6DownPos;
      END_IF;
    END_IF;
    IF g_nFrontSusutainCount >= 4 THEN
      g_bAntiRejection2AbsExecute := TRUE;
      IF AntiRejection2.NCTOPLC.SETPOS <= 0.0 THEN
        g_fARAbsPosition2 := AntiRejection2.NCTOPLC.SETPOS;
      ELSE
        g_fARAbsPosition2 := g_dFrontSustainAxis7DownPos;
      END_IF;
    END_IF;
    nFollowStep := 130;
  130:
    bCheckFlag := TRUE;
    IF g_nFrontSusutainCount >= 1 AND NOT(g_bSustain4AbsDone) THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 2 AND NOT(g_bSustain5AbsDone) THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 3 AND NOT(g_bSustain5AbsDone) THEN
      bCheckFlag := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 4 AND NOT(g_bAntiRejection2AbsDone) THEN
      bCheckFlag := FALSE;
    END_IF;
    IF bCheckFlag THEN
      g_boFrontSustainUpDownDone := TRUE;
      g_bFrontSustainUpDownDone := TRUE;
      nFollowStep := 0;
      M.ENABLE[222] := 0;
      g_bExecuteFinishedM222 := FALSE;
    END_IF;
    140:
    nFollowStep := 150;
    IF g_nBlankClylinderCount >= 1 THEN
      g_bCylinder1Open := FALSE;
      g_bCylinder1Close := TRUE;
    END_IF;
    IF g_nBlankClylinderCount >= 2 THEN
      g_bCylinder2Open := FALSE;
      g_bCylinder2Close := TRUE;
    END_IF;
    IF g_nBlankClylinderCount >= 3 THEN
      g_bCylinder3Open := FALSE;
      g_bCylinder3Close := TRUE;
    END_IF;
    IF g_nBlankClylinderCount >= 4 THEN
      g_bCylinder4Open := FALSE;
      g_bCylinder4Close := TRUE;
    END_IF;
    IF g_nBlankClylinderCount >= 5 THEN
      g_bCylinder5Open := FALSE;
      g_bCylinder5Close := TRUE;
    END_IF;
  150:(*等待到位*)
    bDoneCheckFlag := TRUE;
    IF g_nBlankClylinderCount >= 1 AND NOT g_bBlankingStateDown1 THEN
      bDoneCheckFlag := FALSE;
    END_IF;
    IF g_nBlankClylinderCount >= 2 AND NOT g_bBlankingStateDown2 THEN
      bDoneCheckFlag := FALSE;
    END_IF;
    IF g_nBlankClylinderCount >= 3 AND NOT g_bBlankingStateDown3 THEN
      bDoneCheckFlag := FALSE;
    END_IF;
    IF g_nBlankClylinderCount >= 4 AND NOT g_bBlankingStateDown4 THEN
     bDoneCheckFlag := FALSE;
    END_IF;
    IF g_nBlankClylinderCount >= 5 AND NOT g_bBlankingStateDown5 THEN
      bDoneCheckFlag := FALSE;
    END_IF;
    IF bDoneCheckFlag THEN
        g_boFrontSustainFollowDone := TRUE;
        M.ENABLE[222] := 0;
        g_bExecuteFinishedM222 := FALSE;
        nFollowStep := 0;
    END_IF;
  160:
    (*支撑气缸上升*)
    g_nFrontSustainMoveType := 1;
    g_bFrontSustainUpDown := TRUE;
    nFollowStep := 170;
  170:
    IF g_bFrontSustainUpDownDone THEN
      g_boFrontSustainFollowDone := TRUE;
      M.ENABLE[222] := 0;
      g_bExecuteFinishedM222 := FALSE;
      nFollowStep := 0;
    END_IF; 
  400:
    (*支撑气缸上升*)
    g_nFrontSustainMoveType := 2;
    g_bFrontSustainUpDown := TRUE;
    nFollowStep := 410;
  410:
    IF g_bFrontSustainUpDownDone THEN
      g_boFrontSustainFollowDone := TRUE;
      M.ENABLE[222] := 0;
      g_bExecuteFinishedM222 := FALSE;
      nFollowStep := 0;
    END_IF;
  420:(*开启自动下料，先将升起来的轴降下去*)
    IF g_nFrontSusutainCount >= 1 AND g_dDynamicFollowS1Dis > 0.0 THEN
      g_bSustain4Abs := TRUE;
      IF Axis_Sustain4.NCTOPLC.SETPOS <= 0.0 THEN
          g_bSustain4AbsPosition := Axis_Sustain4.NCTOPLC.SETPOS;
      ELSE
          g_bSustain4AbsPosition := g_dFrontSustainAxis4DownPos;
      END_IF;
    END_IF;
    IF g_nFrontSusutainCount >= 2 AND g_dDynamicFollowS2Dis > 0.0  THEN
       g_bSustain5Abs := TRUE;
      IF Axis_Sustain5.NCTOPLC.SETPOS <= 0.0 THEN
          g_bSustain5AbsPosition := Axis_Sustain5.NCTOPLC.SETPOS;
      ELSE
          g_bSustain5AbsPosition := g_dFrontSustainAxis5DownPos;
      END_IF;
    END_IF;

    IF g_nFrontSusutainCount >= 3 AND g_dDynamicFollowS3Dis > 0.0 THEN
       g_bSustain6Abs := TRUE;
      IF Axis_Sustain6.NCTOPLC.SETPOS <= 0.0   THEN
          g_bSustain6AbsPosition := Axis_Sustain6.NCTOPLC.SETPOS;
      ELSE
          g_bSustain6AbsPosition := g_dFrontSustainAxis6DownPos;
      END_IF;
    END_IF;
    IF g_nFrontSusutainCount >= 4 AND g_dDynamicFollowZ4Dis > 0.0 THEN
       g_bAntiRejection2AbsDone := TRUE;
      IF AntiRejection2.NCTOPLC.SETPOS <= 0.0   THEN
          g_fARAbsPosition2 := AntiRejection2.NCTOPLC.SETPOS;
      ELSE
          g_fARAbsPosition2 := g_dFrontSustainAxis7DownPos;
      END_IF;
    END_IF;
    nFollowStep := 500;
  500:(*到了距离顶升，然后开浮动*)
    fActPos := g_fSustainTargetPos;
    IF g_nFrontSusutainCount >= 1 THEN
      IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS1Dis AND (NOT bDynamicFollowS1Up) AND (NOT g_bSustain4InFollow) THEN
        g_bSustain4AbsPosition := g_fSustain4ToChuckDist - fActPos;
        g_bSustain4Abs := TRUE;
        bDynamicFollowS1Up := TRUE;
      END_IF;
    END_IF;

    IF g_nFrontSusutainCount >= 2 THEN
       IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS2Dis AND (NOT bDynamicFollowS2Up) AND (NOT g_bSustain5InFollow) THEN
         g_bSustain5AbsPosition := g_fSustain5ToChuckDist - fActPos;
          g_bSustain5Abs := TRUE;
          bDynamicFollowS2Up := TRUE;
      END_IF;
    END_IF;

    IF g_nFrontSusutainCount >= 3 THEN
       IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS3Dis AND (NOT bDynamicFollowS3Up) AND (NOT g_bSustain6InFollow) THEN
         g_bSustain6AbsPosition := g_fSustain6ToChuckDist - fActPos;
          g_bSustain6Abs := TRUE;
          bDynamicFollowS3Up := TRUE;
      END_IF;
    END_IF;

    IF g_nFrontSusutainCount >= 4 THEN
       IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowZ4Dis AND (NOT bDynamicFollowS4Up)  THEN
         g_fARAbsPosition2 := g_dFrontSustainAxis7ChuckDist - fActPos;
          g_bAntiRejection2AbsExecute := TRUE;
          bDynamicFollowS4Up := TRUE;
      END_IF;
    END_IF;
    IF bDynamicFollowS1Up OR bDynamicFollowS2Up OR bDynamicFollowS3Up OR bDynamicFollowS4Up THEN
      nFollowStep := 510;
    END_IF;
    IF g_nFrontSusutainCount = 0 THEN
      M.ENABLE[222] := 0;
      g_bExecuteFinishedM222 := FALSE;
      g_boFrontSustainFollowDone := TRUE;
    END_IF;
  510:
   IF NOT((g_nFrontSusutainCount >= 1 AND (NOT g_bSustain4AbsDone)) OR
       (g_nFrontSusutainCount >= 2 AND (NOT g_bSustain5AbsDone)) OR  
       (g_nFrontSusutainCount >= 3 AND (NOT g_bSustain6AbsDone))) THEN
      IF g_nFrontSusutainCount >= 1 AND bDynamicFollowS1Up AND NOT g_bSustain4InFollow  THEN
        IF g_bSustain4AbsDone THEN
          g_bSustain4Follow := TRUE;
        END_IF;
      END_IF;
      IF g_nFrontSusutainCount >= 2 AND bDynamicFollowS2Up AND NOT g_bSustain5InFollow  THEN
         IF g_bSustain5AbsDone THEN
          g_bSustain5Follow := TRUE;
         END_IF;
      END_IF;
      IF g_nFrontSusutainCount >= 3 AND bDynamicFollowS3Up AND NOT g_bSustain6InFollow  THEN
        IF g_bSustain6AbsDone THEN
          g_bSustain6Follow := TRUE;
        END_IF;
      END_IF;
      nFollowStep := 550;
    END_IF;
  550:
   IF  (g_nFrontSusutainCount >= 1 AND g_bSustain4InFollow) OR
       (g_nFrontSusutainCount >= 2 AND g_bSustain5InFollow) OR
       (g_nFrontSusutainCount >= 3 AND g_bSustain6InFollow) THEN
      g_boFrontSustainFollowDone := TRUE;
      M.ENABLE[222] := 0;
      g_bExecuteFinishedM222 := FALSE;
      nFollowStep := 500;
    END_IF;
  600:(*判断当前轴的坐标*)
    fActPos := g_fSustainTargetPos;
	  IF g_nFrontSusutainCount >= 1 AND NOT g_bSustain4InFollow THEN
		g_bSustain4AbsPosition := g_fSustain4ToChuckDist - fActPos;
		g_bSustain4Abs := TRUE;
	  END_IF;
	  IF  g_nFrontSusutainCount >= 2 AND NOT g_bSustain5InFollow THEN
		g_bSustain5AbsPosition := g_fSustain5ToChuckDist - fActPos;
		g_bSustain5Abs := TRUE;
	  END_IF;
	  IF  g_nFrontSusutainCount >= 3 AND NOT g_bSustain6InFollow THEN
		g_bSustain6AbsPosition := g_fSustain6ToChuckDist - fActPos;
		g_bSustain6Abs := TRUE;
	  END_IF;
      IF  g_nFrontSusutainCount >= 4  THEN
		g_fARAbsPosition2 := g_dFrontSustainAxis7ChuckDist - fActPos;
		g_bAntiRejection2AbsExecute := TRUE;
	  END_IF;
	  nFollowStep := 610;
  610:
	  IF (g_nFrontSusutainCount >= 1 AND g_bSustain4AbsDone) OR
		(g_nFrontSusutainCount >= 2 AND g_bSustain5AbsDone) OR 
		(g_nFrontSusutainCount >= 3 AND g_bSustain6AbsDone) THEN
		g_bSustain4Follow := TRUE;
		g_bSustain5Follow := TRUE;
		g_bSustain6Follow := TRUE;
		  g_boFrontSustainFollowDone := TRUE;
		  M.ENABLE[222] := 0;
		  g_bExecuteFinishedM222 := FALSE;
		  nFollowStep := 0;
		END_IF;

END_CASE;
RTrigger5(CLK := g_bFrontSustainAxisFloatControlM);
IF RTrigger5.Q THEN
  g_bFrontSustainAxisFloatControlM := FALSE;
  IF g_nFrontSustainSignalM = 1.0 THEN
	nFrontSustainAxisFollowState := 10;
  ELSE
    nFrontSustainAxisFollowState := 100;
  END_IF;
  IF g_nFrontSusutainCount = 0 THEN
    nFrontSustainAxisFollowState := 0;
    M.ENABLE[222] := 0;
    g_bExecuteFinishedM222 := FALSE;
    g_boFrontSustainFollowDone := TRUE;
  END_IF;
END_IF;



CASE nFrontSustainAxisFollowState OF
  0:
	nFrontSustainAxisFollowState := 0;
  10:
	IF g_nFrontSusutainCount >= 1 THEN
      nFrontSustainAxis1FollowState := 10;
		IF g_bFrontAxis1VelAddEnable THEN
		   g_bFrontAxis1VelAddEnable := FALSE;
		END_IF;
    END_IF;
    IF g_nFrontSusutainCount >= 2 THEN
      nFrontSustainAxis2FollowState := 10;
		IF g_bFrontAxis2VelAddEnable THEN
		   g_bFrontAxis2VelAddEnable := FALSE;
		END_IF;
    END_IF;
    IF g_nFrontSusutainCount >= 3 THEN
      nFrontSustainAxis3FollowState := 10;
		IF g_bFrontAxis3VelAddEnable THEN
		   g_bFrontAxis3VelAddEnable := FALSE;
		END_IF;
    END_IF;

    IF g_nFrontSusutainCount >= 4 THEN
      nFrontSustainAxis4FollowState := 10;
		IF g_bFrontAxis4VelAddEnable THEN
		   g_bFrontAxis4VelAddEnable := FALSE;
		END_IF;
    END_IF;
    nFrontSustainAxisFollowState := 20;
  20:
	bFrontSustainAxisFollowCheck := TRUE;
    IF g_nFrontSusutainCount >= 1 AND NOT g_bSustain4AbsDone THEN
      bFrontSustainAxisFollowCheck := FALSE;
    END_IF;
     IF g_nFrontSusutainCount >= 2 AND NOT g_bSustain5AbsDone THEN
      bFrontSustainAxisFollowCheck := FALSE;
    END_IF;
     IF g_nFrontSusutainCount >= 3 AND NOT g_bSustain6AbsDone THEN
      bFrontSustainAxisFollowCheck := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 4 AND NOT g_bAntiRejection2AbsDone THEN
      bFrontSustainAxisFollowCheck := FALSE;
    END_IF;
	IF bFrontSustainAxisFollowCheck THEN
      nFrontSustainAxisFollowState := 200;
    END_IF;
  100:
    IF g_nFrontSusutainCount >= 1 THEN
		nFrontSustainAxis1FollowState := 100;
		g_bFrontAxis1VelAddEnable := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 2 THEN
		nFrontSustainAxis2FollowState := 100;
		g_bFrontAxis2VelAddEnable := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 3 THEN
		nFrontSustainAxis3FollowState := 100;
		g_bFrontAxis3VelAddEnable := FALSE;
    END_IF;
     IF g_nFrontSusutainCount >= 4 THEN
		nFrontSustainAxis4FollowState := 100;
		g_bFrontAxis4VelAddEnable := FALSE;
    END_IF;
     nFrontSustainAxisFollowState := 120;
  120:
	bFrontSustainAxisFollowCheck := TRUE;
    IF g_nFrontSusutainCount >= 1 AND NOT g_bSustain4AbsDone THEN
      bFrontSustainAxisFollowCheck := FALSE;
    END_IF;
     IF g_nFrontSusutainCount >= 2 AND NOT g_bSustain5AbsDone THEN
      bFrontSustainAxisFollowCheck := FALSE;
    END_IF;
     IF g_nFrontSusutainCount >= 3 AND NOT g_bSustain6AbsDone THEN
      bFrontSustainAxisFollowCheck := FALSE;
    END_IF;
    IF g_nFrontSusutainCount >= 4 AND NOT g_bAntiRejection2AbsDone THEN
      bFrontSustainAxisFollowCheck := FALSE;
    END_IF;
	IF bFrontSustainAxisFollowCheck THEN
      nFrontSustainAxisFollowState := 200;
    END_IF;
  200:
	nFrontSustainAxisFollowState := 0;
    M.ENABLE[222] := 0;
    g_bExecuteFinishedM222 := FALSE;
    g_boFrontSustainFollowDone := TRUE;

END_CASE;



(*M代码触发单个托料轴浮动开关*)
RTrigger4(CLK := g_bFrontSustainAxisFollowControlM);
IF RTrigger4.Q THEN
  (*托料轴1加耦浮动*)
  IF g_nFrontSustainSignalM = 11.0 THEN
    nFrontSustainAxis1FollowState := 10;
    IF g_bFrontAxis1VelAddEnable THEN
       g_bFrontAxis1VelAddEnable := FALSE;
    END_IF;
  (*托料轴1解耦下降*)
  ELSIF g_nFrontSustainSignalM = 12.0 THEN
    nFrontSustainAxis1FollowState := 100;
    g_bFrontAxis1VelAddEnable := FALSE;
  (*托料轴2加耦浮动*)
  ELSIF g_nFrontSustainSignalM = 13.0 THEN
    nFrontSustainAxis2FollowState := 10;
    IF g_bFrontAxis2VelAddEnable THEN
       g_bFrontAxis2VelAddEnable := FALSE;
    END_IF;
  (*托料轴2解耦下降*)
  ELSIF g_nFrontSustainSignalM = 14.0 THEN
    nFrontSustainAxis2FollowState := 100;
    g_bFrontAxis2VelAddEnable := FALSE;
  (*托料轴3加耦浮动*)
  ELSIF g_nFrontSustainSignalM = 15.0 THEN
    nFrontSustainAxis3FollowState := 10;
    IF g_bFrontAxis3VelAddEnable THEN
       g_bFrontAxis3VelAddEnable := FALSE;
    END_IF;
  (*托料轴3解耦下降*)
  ELSIF g_nFrontSustainSignalM = 16.0 THEN
    nFrontSustainAxis3FollowState := 100;
    g_bFrontAxis3VelAddEnable := FALSE;
  (*托料轴4加耦浮动*)
  ELSIF g_nFrontSustainSignalM = 17.0 THEN
    nFrontSustainAxis4FollowState := 10;
    IF g_bFrontAxis4VelAddEnable THEN
       g_bFrontAxis4VelAddEnable := FALSE;
    END_IF;
  (*托料轴4解耦下降*)
  ELSIF g_nFrontSustainSignalM = 18.0 THEN
    nFrontSustainAxis4FollowState := 100;
    g_bFrontAxis4VelAddEnable := FALSE;
  ELSIF g_nFrontSustainSignalM = 100.0 THEN(*新增指令:P100:控制轴的零件间的托举是否要执行Q:0:关闭1:开启 I:1-3*)
    IF M.PARAMETER_I[222] = 1.0 THEN
      g_bFrontSustainAxis1CloseVelAdd := NOT LREAL_TO_BOOL(M.PARAMETER_Q[222]);
      IF NOT g_bFrontSustainAxis1CloseVelAdd THEN
        nFrontSustainAxis1FollowState := 200;
        bAxis1P100TriggerFlag := TRUE;
      END_IF;
		IF g_bFrontAxis1VelAddEnable THEN
		   g_bFrontAxis1VelAddEnable := FALSE;
		END_IF;
    ELSIF M.PARAMETER_I[222] = 2.0 THEN
      g_bFrontSustainAxis2CloseVelAdd := NOT LREAL_TO_BOOL(M.PARAMETER_Q[222]);
      IF NOT g_bFrontSustainAxis2CloseVelAdd THEN
        nFrontSustainAxis2FollowState := 200;
        bAxis2P100TriggerFlag := TRUE;
      END_IF;
		IF g_bFrontAxis2VelAddEnable THEN
		   g_bFrontAxis2VelAddEnable := FALSE;
		END_IF;
    ELSIF M.PARAMETER_I[222] = 3.0 THEN 
      g_bFrontSustainAxis3CloseVelAdd := NOT LREAL_TO_BOOL(M.PARAMETER_Q[222]);
      IF NOT g_bFrontSustainAxis3CloseVelAdd THEN
        nFrontSustainAxis3FollowState := 200;
        bAxis3P100TriggerFlag := TRUE;
      END_IF;
		IF g_bFrontAxis3VelAddEnable THEN
		   g_bFrontAxis3VelAddEnable := FALSE;
		END_IF;
    ELSIF M.PARAMETER_I[222] = 4.0 THEN 
      g_bFrontSustainAxis4CloseVelAdd := NOT LREAL_TO_BOOL(M.PARAMETER_Q[222]);
      IF NOT g_bFrontSustainAxis4CloseVelAdd THEN
        nFrontSustainAxis4FollowState := 200;
        bAxis4P100TriggerFlag := TRUE;
      END_IF;
		IF g_bFrontAxis4VelAddEnable THEN
		   g_bFrontAxis4VelAddEnable := FALSE;
		END_IF;
    END_IF;
    M.ENABLE[222] :=0;
  END_IF;
  g_bFrontSustainAxisFollowControlM := FALSE;
END_IF;

(*托料轴1*)
CASE nFrontSustainAxis1FollowState OF
  0:
	nFrontSustainAxis1FollowState := 0;
  10:
	fActPos := g_fSustainTargetPos;
    g_bSustain4AbsPosition := g_fSustain4ToChuckDist - fActPos;
    g_bSustain4Abs := TRUE;
    g_bFrontAxis1VelAddEnable := TRUE;
    nFrontSustainAxis1FollowState := 20;
    g_bSustain4AbsDone := FALSE;
  20:
	IF g_bSustain4AbsDone THEN
      g_bSustain4Abs := FALSE;
      M.ENABLE[222] := 0;
	  g_boFrontSustainFollowDone := TRUE;
      bDynamicFollowS1Up := FALSE;
      g_bFinishedM222_11 := FALSE;
    END_IF;
	  IF g_bPlcPauseBuffer THEN
		  nFrontSustainAxis1FollowState := 40;
	  END_IF;
  40:
	  IF g_bPlcStartBuffer THEN
		nFrontSustainAxis1FollowState := 10;
	  END_IF;
  100:
	  g_Sustain4Stop.EXECUTE := TRUE;
      IF g_Sustain4Stop.DONE THEN
         g_Sustain4Stop.EXECUTE := FALSE;
		nFrontSustainAxis1FollowState := 110;
      END_IF;
  110:
	  g_boFrontSustainFollowDone := TRUE;
	  g_boFrontSustainUpDownDone := FALSE;
	  g_bFrontSustainUpDownDone := FALSE;
	  nFrontSustainAxis1FollowState := 120;
  120:
	  g_bSustain4Abs := TRUE;
      g_bSustain4AbsPosition := g_dFrontSustainAxis4DownPos;
	  g_bSustain4AbsDone := FALSE;
	  nFrontSustainAxis1FollowState := 130;
  130:
	  IF g_bSustain4AbsDone THEN
		g_boFrontSustainUpDownDone := TRUE;
		g_bFrontSustainUpDownDone := TRUE;
		nFrontSustainAxis1FollowState := 0;
		M.ENABLE[222] := 0;
		g_bFinishedM222_12 := FALSE;
        bDynamicFollowS1Up := TRUE;
	  END_IF;
      IF g_bPlcPauseBuffer THEN
		  nFrontSustainAxis1FollowState := 140;
	  END_IF;
  140:
	 IF g_bPlcStartBuffer THEN
		nFrontSustainAxis1FollowState := 120;
	  END_IF;
  200:
	fActPos := g_fSustainTargetPos;
    IF g_nFrontSusutainCount >= 1 THEN
       IF g_diYMachineCoordinate - g_dDynamicCoordTemp >= g_dDynamicFollowS1Dis  AND NOT g_bFrontSustainAxis1CloseVelAdd THEN
		  g_bSustain4AbsPosition := g_fSustain4ToChuckDist - fActPos;
		  g_bSustain4Abs := TRUE;
		  g_bFrontAxis1VelAddEnable := TRUE;
          nFrontSustainAxis1FollowState := 0;
        END_IF;
        IF bAxis1P100TriggerFlag THEN
          M.ENABLE[222] := 0;
          g_bFinishedM222_11 := FALSE;
          bAxis1P100TriggerFlag := FALSE;
        END_IF;
    ELSE
      M.ENABLE[222] := 0;
      g_bFinishedM222_11 := FALSE;
	  nFrontSustainAxis1FollowState := 0;
      bAxis1P100TriggerFlag := FALSE;
    END_IF;
END_CASE;

